public with sharing class OpportunityPipelineHandler {

    /**
     * Entry point for the Opportunity trigger. Determines which Accounts are
     * affected by the current DML and recomputes their open-pipeline fields
     * from the database. Recomputing (rather than applying incremental deltas)
     * keeps the totals correct even when several DML statements touch the same
     * records in one transaction and when other triggers re-enter this one.
     */
    public static void handle(Map<Id, Opportunity> oldMap, Map<Id, Opportunity> newMap) {
        Set<Id> accountIds = collectAffectedAccountIds(oldMap, newMap);
        if (accountIds.isEmpty()) {
            return;
        }
        recalculate(accountIds);
    }

    /**
     * Works out every Account whose open-pipeline totals could have changed:
     *  - insert:   the new AccountId
     *  - delete:   the old AccountId
     *  - undelete: the new AccountId
     *  - update:   if Amount, IsClosed/StageName or AccountId changed, then
     *              both the old and the new AccountId (reparenting)
     */
    private static Set<Id> collectAffectedAccountIds(Map<Id, Opportunity> oldMap, Map<Id, Opportunity> newMap) {
        Set<Id> accountIds = new Set<Id>();

        if (newMap != null && oldMap == null) {
            // insert or undelete
            for (Opportunity o : newMap.values()) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        } else if (newMap == null && oldMap != null) {
            // delete
            for (Opportunity o : oldMap.values()) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        } else if (newMap != null && oldMap != null) {
            // update
            for (Opportunity newOpp : newMap.values()) {
                Opportunity oldOpp = oldMap.get(newOpp.Id);

                Boolean amountChanged   = newOpp.Amount != oldOpp.Amount;
                Boolean openStateChanged = newOpp.IsClosed != oldOpp.IsClosed;
                Boolean accountChanged  = newOpp.AccountId != oldOpp.AccountId;

                if (amountChanged || openStateChanged || accountChanged) {
                    if (newOpp.AccountId != null) {
                        accountIds.add(newOpp.AccountId);
                    }
                    if (oldOpp.AccountId != null) {
                        accountIds.add(oldOpp.AccountId);
                    }
                }
            }
        }

        return accountIds;
    }

    /**
     * Recomputes FB_Open_Pipeline__c and FB_Open_Opportunities__c for the given
     * Accounts from the current open opportunities in the database. Accounts
     * with no open opportunities are reset to 0/0. Only Accounts whose values
     * actually change are updated, which also prevents infinite recursion when
     * the AccountTrigger re-enters this handler.
     */
    private static void recalculate(Set<Id> accountIds) {
        // Default every affected account to zero so that accounts whose last
        // open opportunity has gone away show 0/0 rather than blank.
        Map<Id, Decimal> sumByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();
        for (Id accId : accountIds) {
            sumByAccount.put(accId, 0);
            countByAccount.put(accId, 0);
        }

        for (AggregateResult ar : [
            SELECT AccountId acc, SUM(Amount) total, COUNT(Id) cnt
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('acc');
            Decimal total = (Decimal) ar.get('total'); // null when all amounts blank
            Integer cnt = (Integer) ar.get('cnt');
            sumByAccount.put(accId, total == null ? 0 : total);
            countByAccount.put(accId, cnt == null ? 0 : cnt);
        }

        // Load current values so we only update rows that genuinely change.
        List<Account> toUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal newPipeline = sumByAccount.get(acc.Id);
            Integer newCount = countByAccount.get(acc.Id);

            Decimal currentPipeline = acc.FB_Open_Pipeline__c;
            Decimal currentCount = acc.FB_Open_Opportunities__c;

            Boolean pipelineDiffers =
                currentPipeline == null || currentPipeline != newPipeline;
            Boolean countDiffers =
                currentCount == null || currentCount != newCount;

            if (pipelineDiffers || countDiffers) {
                acc.FB_Open_Pipeline__c = newPipeline;
                acc.FB_Open_Opportunities__c = newCount;
                toUpdate.add(acc);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
```

