```apex
public with sharing class Opportunities extends fflib_SObjectDomain
{
    public Opportunities(List<Opportunity> sObjectList)
    {
        super(sObjectList);
        // Don't enforce object/FLS security here so validation always runs
        Configuration.disableTriggerCRUDSecurity();
    }

    public override void onBeforeInsert()
    {
        validateInsert();
    }

    public override void onBeforeUpdate(Map<Id, SObject> existingRecords)
    {
        validateUpdate(existingRecords);
    }

    // Keep standard validation hooks wired too, for completeness / after-context callers
    public override void onValidate()
    {
        validateInsert();
    }

    public override void onValidate(Map<Id, SObject> existingRecords)
    {
        validateUpdate(existingRecords);
    }

    private void validateInsert()
    {
        for (Opportunity opp : (List<Opportunity>) Records)
        {
            validateAmountNotNegative(opp);
        }
    }

    private void validateUpdate(Map<Id, SObject> existingRecords)
    {
        for (Opportunity opp : (List<Opportunity>) Records)
        {
            validateAmountNotNegative(opp);

            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);

            // Only block if the opportunity was ALREADY Closed Won before this update
            if (oldOpp != null
                && oldOpp.StageName == 'Closed Won'
                && opp.Amount != oldOpp.Amount)
            {
                error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
            }
        }
    }

    private void validateAmountNotNegative(Opportunity opp)
    {
        if (opp.Amount != null && opp.Amount < 0)
        {
            error('Amount cannot be negative.', opp, Opportunity.Amount);
        }
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }
}
