/**
 * Fires survey feedback follow-up when a Case transitions to Closed.
 *
 * Design note: the requirement asked for one Queueable per case, but synchronous
 * Apex is capped at 50 System.enqueueJob calls per transaction. Bulk list-view
 * closes and the nightly 200-record API job would exceed that and throw a
 * LimitException, failing the whole update. Instead we enqueue a SINGLE
 * CaseSurveyJob for the batch of newly-closed cases. The job processes each case
 * independently (partial-success insert), so one bad record still cannot affect
 * the others.
 */
trigger CaseTrigger on Case (after update) {
    Set<Id> newlyClosedCaseIds = new Set<Id>();

    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);
        // Only act on the transition from not-closed to closed.
        if (c.IsClosed && !oldCase.IsClosed) {
            newlyClosedCaseIds.add(c.Id);
        }
    }

    if (!newlyClosedCaseIds.isEmpty()) {
        System.enqueueJob(new CaseSurveyJob(newlyClosedCaseIds));
    }
}
