/**
 * Service that records monthly giving sign-ups as NPSP Enhanced Recurring Donations.
 *
 * NPSP (with Enhanced Recurring Donations enabled) is responsible for generating the
 * installment Opportunities asynchronously after the npe03__Recurring_Donation__c records
 * are inserted, so this service never creates Opportunities itself.
 */
public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    /**
     * Creates one Enhanced Recurring Donation per request and returns the new Ids in
     * request order.
     *
     * Bulk-safe: validates every request up front (throwing before any DML on the first
     * invalid request), then performs a single insert for the whole batch.
     *
     * @param requests the monthly gift sign-ups
     * @return the Ids of the created recurring donations, in the same order as requests
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> result = new List<Id>();

        if (requests == null || requests.isEmpty()) {
            return result;
        }

        // Validate all requests before performing any DML.
        for (GiftRequest req : requests) {
            if (req == null) {
                throw new RecurringGiftException('Request cannot be null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException('Each request must have a contact.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('Each request must have a positive amount.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException('dayOfMonth must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('Each request must have a start date.');
            }
        }

        // Build the recurring donation records.
        List<npe03__Recurring_Donation__c> toInsert =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {
            Boolean openEnded = (req.installments == null || req.installments == 0);

            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();
            rd.npe03__Contact__c = req.contactId;
            rd.npe03__Amount__c = req.amount;

            // Monthly schedule, every month, on the requested day.
            rd.npe03__Installment_Period__c = 'Monthly';
            rd.npsp__InstallmentFrequency__c = 1;

            // Enhanced RD day-of-month handling: "31" means last day of month.
            // Enhanced RD stores the last-day option as day-of-month '30' with the
            // Always_Use_Last_Day_Of_Month flag set to true; that flag is what
            // distinguishes "the last day" from "the 30th".
            if (req.dayOfMonth == 31) {
                rd.npsp__Always_Use_Last_Day_Of_Month__c = true;
                rd.npsp__Day_of_Month__c = '30';
            } else {
                rd.npsp__Always_Use_Last_Day_Of_Month__c = false;
                rd.npsp__Day_of_Month__c = String.valueOf(req.dayOfMonth);
            }

            // Dates.
            rd.npsp__StartDate__c = req.startDate;
            rd.npe03__Date_Established__c = req.startDate;

            // Open-ended vs. fixed-length.
            if (openEnded) {
                rd.npsp__RecurringType__c = 'Open';
            } else {
                rd.npsp__RecurringType__c = 'Fixed';
                rd.npe03__Installments__c = req.installments;
            }

            // Active status.
            rd.npsp__Status__c = 'Active';

            // Payment method.
            rd.npsp__PaymentMethod__c = req.paymentMethod;

            toInsert.add(rd);
        }

        // Single DML statement for the whole batch. NPSP triggers will generate the
        // installment Opportunities asynchronously.
        insert toInsert;

        for (npe03__Recurring_Donation__c rd : toInsert) {
            result.add(rd.Id);
        }

        return result;
    }
}
```

**What changed:**

- The restricted picklist `npsp__Day_of_Month__c` does not accept a `'Last Day'` value. In Enhanced Recurring Donations, "last day of the month" is modeled as day-of-month `'30'` together with `npsp__Always_Use_Last_Day_Of_Month__c = true`. The boolean flag is the field that actually drives last-day behavior, so for `dayOfMonth == 31` I now set `npsp__Day_of_Month__c = '30'` and the flag to `true`. Days 29 and 30 continue to be stored as their literal values with the flag `false`, as required.

