public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        // --- Validate inputs ------------------------------------------------
        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('A non-empty map of GAU Id to percentage is required.');
        }

        Decimal total = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A GAU Id in the map was null.');
            }
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null) {
                throw new AllocationException('Percentage for GAU ' + gauId + ' is null.');
            }
            if (pct <= 0) {
                throw new AllocationException('Percentage for GAU ' + gauId + ' must be greater than 0.');
            }
            total += pct;
        }

        if (total > 100) {
            throw new AllocationException('The sum of percentages (' + total + ') exceeds 100.');
        }

        // --- Verify every GAU exists and is active --------------------------
        Map<Id, npsp__General_Accounting_Unit__c> gaus = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :percentByGauId.keySet()
            ]
        );

        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gaus.get(gauId);
            if (gau == null) {
                throw new AllocationException('GAU ' + gauId + ' does not exist or is not accessible.');
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('GAU ' + gauId + ' is inactive.');
            }
        }

        // --- Build the new allocations (validate before mutating data) ------
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                // Use Percent (not Amount) so NPSP recalculates the amount
                // automatically whenever the Opportunity amount changes.
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        // --- Replace existing allocations only after all validation passes --
        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existing.isEmpty()) {
            delete existing;
        }

        insert newAllocations;

        return newAllocations;
    }
}
