public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // Gather the opportunity and contact ids referenced by the requests.
        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req != null) {
                if (req.opportunityId != null) {
                    opportunityIds.add(req.opportunityId);
                }
                if (req.contactId != null) {
                    contactIds.add(req.contactId);
                }
            }
        }

        // SOQL 1: load opportunities (amount + primary contact) for validation.
        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>(
            [
                SELECT Id, Amount, npsp__Primary_Contact__c
                FROM Opportunity
                WHERE Id IN :opportunityIds
            ]
        );

        // Validate the entire call before any DML.
        for (SoftCreditRequest req : requests) {
            if (req == null) {
                throw new SoftCreditException('A soft credit request was null.');
            }

            Opportunity opp = opportunitiesById.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity ' + req.opportunityId + ' was not found.'
                );
            }

            if (req.contactId != null && opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId +
                    ' is the primary contact on opportunity ' + req.opportunityId +
                    ' and cannot receive a soft credit.'
                );
            }

            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException(
                    'Soft credit amount must be a positive value for opportunity ' +
                    req.opportunityId + ' and contact ' + req.contactId + '.'
                );
            }

            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount cannot exceed the opportunity amount for opportunity ' +
                    req.opportunityId + ' and contact ' + req.contactId + '.'
                );
            }
        }

        // SOQL 2: existing OpportunityContactRoles for the opp/contact pairs involved.
        // We need exactly one role per contact per opportunity, with Role == requested role.
        Map<String, OpportunityContactRole> ocrByKey =
            new Map<String, OpportunityContactRole>();
        // All existing roles grouped so we can delete any extras.
        Map<String, List<OpportunityContactRole>> allOcrByKey =
            new Map<String, List<OpportunityContactRole>>();

        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
              AND ContactId IN :contactIds
        ]) {
            String key = ocr.OpportunityId + '|' + ocr.ContactId;
            if (!allOcrByKey.containsKey(key)) {
                allOcrByKey.put(key, new List<OpportunityContactRole>());
            }
            allOcrByKey.get(key).add(ocr);
        }

        // SOQL 3: existing partial soft credits for the opp/contact pairs involved.
        Map<String, npsp__Partial_Soft_Credit__c> pscByKey =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
              AND npsp__Contact__c IN :contactIds
        ]) {
            String key = psc.npsp__Opportunity__c + '|' + psc.npsp__Contact__c;
            pscByKey.put(key, psc);
        }

        // Build the DML collections.
        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();

        // Track which request each new OCR corresponds to so we can wire up the PSC
        // after insert (new OCRs do not have an Id until inserted).
        List<SoftCreditRequest> requestsNeedingInsertedOcr = new List<SoftCreditRequest>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '|' + req.contactId;
            List<OpportunityContactRole> existing = allOcrByKey.get(key);

            OpportunityContactRole target;
            if (existing == null || existing.isEmpty()) {
                // No OCR yet - create one.
                target = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrsToInsert.add(target);
                requestsNeedingInsertedOcr.add(req);
            } else {
                // Keep the first (non-primary preferred) role, set its Role, delete extras.
                target = pickKeeper(existing);
                if (target.Role != req.role) {
                    target.Role = req.role;
                }
                ocrsToUpdate.add(target);
                for (OpportunityContactRole ocr : existing) {
                    if (ocr.Id != target.Id) {
                        ocrsToDelete.add(ocr);
                    }
                }
            }
            ocrByKey.put(key, target);
        }

        // DML 1: delete extra OCRs so the contact ends with exactly one role.
        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }

        // DML 2: update existing kept OCRs with the requested role.
        if (!ocrsToUpdate.isEmpty()) {
            update ocrsToUpdate;
        }

        // DML 3: insert new OCRs; after this they have Ids.
        if (!ocrsToInsert.isEmpty()) {
            insert ocrsToInsert;
        }

        // Build / update partial soft credits.
        List<npsp__Partial_Soft_Credit__c> pscsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '|' + req.contactId;
            OpportunityContactRole ocr = ocrByKey.get(key);

            npsp__Partial_Soft_Credit__c psc = pscByKey.get(key);
            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId
                );
            }
            psc.npsp__Amount__c = req.amount;
            psc.npsp__Role_Name__c = req.role;
            psc.npsp__Contact_Role_ID__c = ocr.Id;
            pscsToUpsert.add(psc);
        }

        // DML 4: upsert the partial soft credits.
        if (!pscsToUpsert.isEmpty()) {
            upsert pscsToUpsert;
        }
    }

    // Choose which existing OCR to keep: prefer a non-primary role so we never
    // disturb/retype the opportunity's primary contact role.
    private static OpportunityContactRole pickKeeper(List<OpportunityContactRole> ocrs) {
        for (OpportunityContactRole ocr : ocrs) {
            if (ocr.IsPrimary != true) {
                return ocr;
            }
        }
        return ocrs[0];
    }
}
