public with sharing class FamilyService {

    /**
     * Links each child Contact to their parent Contact in NPSP.
     *
     * For each (childId => parentId) pair we insert a single relationship record
     * in the child -> parent direction with Type "Parent" and Status "Current".
     *
     * Because this org uses the NPSP "List Setting" reciprocal method, the NPSP
     * REL_Relationships_TDTM trigger handler automatically creates the matching
     * reciprocal record (parent -> child) using the Relationship Lookup for
     * "Parent" (Male: Son, Female: Daughter, Neutral: Child) and wires the two
     * records together via npe4__ReciprocalRelationship__c. We therefore insert
     * only one record per pair to avoid duplicates.
     *
     * Pairs are skipped when any relationship already exists between the two
     * contacts in either direction, so the import can be re-run safely.
     *
     * @param parentIdByChildId  child Contact Id => parent Contact Id
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Null or empty input does nothing.
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect every Contact Id involved so we can query all existing
        // relationships touching any of them in a single SOQL statement.
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) {
                continue;
            }
            contactIds.add(childId);
            contactIds.add(parentId);
        }

        if (contactIds.isEmpty()) {
            return;
        }

        // 1 SOQL: find every relationship between any of the involved contacts.
        // We record each existing linkage as an order-independent pair key so
        // that a relationship in either direction causes the pair to be skipped.
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
              AND npe4__RelatedContact__c IN :contactIds
        ]) {
            existingPairKeys.add(buildPairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        Set<String> plannedPairKeys = new Set<String>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            // Guard against null/empty endpoints and self-relationships.
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String pairKey = buildPairKey(childId, parentId);

            // Skip if a relationship already exists between the two contacts,
            // or if we have already planned one for this pair in this call
            // (e.g. duplicate pairs within the input).
            if (existingPairKeys.contains(pairKey) || plannedPairKeys.contains(pairKey)) {
                continue;
            }
            plannedPairKeys.add(pairKey);

            // Insert only the child -> parent direction; NPSP creates the
            // reciprocal (parent -> child as Son/Daughter/Child) automatically.
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
