public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        // Verify object-level read access first so we never throw if the
        // running user cannot read FB_Employee__c at all.
        if (!Schema.SObjectType.FB_Employee__c.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        Map<String, Schema.SObjectField> fieldMap =
            Schema.SObjectType.FB_Employee__c.fields.getMap();

        // Always-selectable identifiers, then only the custom fields the
        // running user can actually read. Fields the user cannot read are
        // simply never queried, so they are absent (not null) in the results.
        List<String> fieldsToQuery = new List<String>{ 'Id', 'Name' };
        for (String fieldName : new List<String>{
                'Department__c', 'Salary__c', 'Personal_Email__c' }) {
            Schema.SObjectField field = fieldMap.get(fieldName);
            if (field != null && field.getDescribe().isAccessible()) {
                fieldsToQuery.add(fieldName);
            }
        }

        // "with sharing" on the class plus USER_MODE keep sharing and
        // object/field security enforced; since we only select readable
        // fields, USER_MODE will not throw.
        String soql =
            'SELECT ' + String.join(fieldsToQuery, ', ') +
            ' FROM FB_Employee__c' +
            ' WITH USER_MODE' +
            ' ORDER BY Name ASC';

        return Database.query(soql);
    }
}
