public inherited sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    @TestVisible
    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        enforce((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        List<Contact> oldContacts = (List<Contact>) triggerOld;
        Map<Id, Contact> oldById = new Map<Id, Contact>();
        for (Contact oldContact : oldContacts) {
            oldById.put(oldContact.Id, oldContact);
        }
        enforce(newContacts, oldById);
    }

    /**
     * @param newContacts the records being saved (Trigger.new)
     * @param oldById     map of old record values keyed by Id, or null for insert context
     */
    private void enforce(List<Contact> newContacts, Map<Id, Contact> oldById) {
        // Candidates that must be checked (have Account + Email, and for update, changed).
        List<Contact> candidates = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<Id> recordIds = new Set<Id>();

        for (Contact con : newContacts) {
            if (con.AccountId == null || String.isBlank(con.Email)) {
                continue;
            }
            if (oldById != null) {
                Contact oldContact = oldById.get(con.Id);
                Boolean emailChanged = oldContact == null
                    || !emailsEqual(oldContact.Email, con.Email);
                Boolean accountChanged = oldContact == null
                    || oldContact.AccountId != con.AccountId;
                if (!emailChanged && !accountChanged) {
                    continue;
                }
            }
            candidates.add(con);
            accountIds.add(con.AccountId);
            if (con.Id != null) {
                recordIds.add(con.Id);
            }
        }

        if (candidates.isEmpty()) {
            return;
        }

        // Build the set of taken (AccountId + lower-cased Email) keys from the database.
        // One SOQL query for the whole trigger execution.
        Set<String> takenKeys = new Set<String>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != null
            AND Id NOT IN :recordIds
            WITH USER_MODE
        ]) {
            takenKeys.add(buildKey(existing.AccountId, existing.Email));
        }

        // Keys claimed within this same save; first record in the list wins.
        Set<String> claimedInBatch = new Set<String>();

        for (Contact con : candidates) {
            String key = buildKey(con.AccountId, con.Email);
            if (takenKeys.contains(key) || claimedInBatch.contains(key)) {
                con.addError(ERROR_MESSAGE);
            } else {
                claimedInBatch.add(key);
            }
        }
    }

    private Boolean emailsEqual(String a, String b) {
        String aNorm = a == null ? null : a.trim().toLowerCase();
        String bNorm = b == null ? null : b.trim().toLowerCase();
        return aNorm == bNorm;
    }

    private String buildKey(Id accountId, String email) {
        return String.valueOf(accountId) + '::' + email.trim().toLowerCase();
    }
}
