/**
 * Before-insert trigger action for Contact.
 *
 * When a new contact has an Account and a blank LeadSource, set it to the account's
 * AccountSource.
 *
 * Reads parent accounts from the shared TA_Contact_Queries singleton; it does not
 * query Accounts itself.
 */
public inherited sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (Contact con : (List<Contact>) triggerNew) {
            if (con.AccountId == null || String.isNotBlank(con.LeadSource)) {
                continue;
            }

            Account parent = accountsById.get(con.AccountId);
            if (parent == null) {
                continue;
            }

            con.LeadSource = parent.AccountSource;
        }
    }
